<script setup lang="ts">
import{computed,onMounted,reactive,ref}from'vue';import{createMetric,getMeasurements,saveEntry}from'../services/measurementService';import type{MeasurementOverview,Metric}from'../types/measurement'
const data=ref<MeasurementOverview|null>(null),selectedId=ref(''),showNew=ref(false),showEntry=ref(false),loading=ref(true),error=ref(''),success=ref('');const today=new Date().toLocaleDateString('en-CA')
const metricForm=reactive({name:'',category:'Rendimiento',unit:'repeticiones',direction:'HigherIsBetter',targetValue:null as number|null,targetDate:'',protocol:'',sourceTitle:'',sourceUrl:''});const entryForm=reactive({date:today,value:null as number|null,conditions:'',notes:''})
const selected=computed(()=>data.value?.metrics.find(x=>x.id===selectedId.value)??null);const maxValue=computed(()=>Math.max(1,...(selected.value?.entries.map(x=>x.value)??[])));function fmt(d:string|null){return d?new Date(`${d}T00:00:00`).toLocaleDateString('es-AR'):'—'};function fail(e:unknown){error.value=e instanceof Error?e.message:'Ocurrió un error.'}
async function load(){loading.value=true;try{data.value=await getMeasurements();selectedId.value=data.value.metrics[0]?.id??''}catch(e){fail(e)}finally{loading.value=false}}
function replace(m:Metric){if(!data.value)return;const i=data.value.metrics.findIndex(x=>x.id===m.id);if(i>=0)data.value.metrics[i]=m;else data.value.metrics.push(m);selectedId.value=m.id}
async function addMetric(){try{const m=await createMetric({...metricForm,targetDate:metricForm.targetDate||null});replace(m);showNew.value=false;success.value='Indicador creado. Ahora podés registrar su primera medición.';Object.assign(metricForm,{name:'',category:'Rendimiento',unit:'repeticiones',direction:'HigherIsBetter',targetValue:null,targetDate:'',protocol:'',sourceTitle:'',sourceUrl:''})}catch(e){fail(e)}}
async function addEntry(){if(!selected.value||entryForm.value===null)return;try{replace(await saveEntry(selected.value.id,entryForm));showEntry.value=false;success.value='Medición guardada con su fecha y condiciones.';Object.assign(entryForm,{date:today,value:null,conditions:'',notes:''})}catch(e){fail(e)}}
onMounted(load)
</script>
<template><section class="page measurements-page" :class="{muted:loading}"><div class="page-heading"><div><span class="eyebrow">Evaluaciones</span><h1>Mediciones y marcas</h1><p>Seguimiento personal con unidad, protocolo y objetivo explícitos.</p></div><button class="primary-button" @click="showNew=!showNew">Nuevo indicador</button></div><div v-if="error" class="notice error">{{error}}</div><div v-if="success" class="notice atlas-success">{{success}}</div><form v-if="showNew" class="panel metric-form" @submit.prevent="addMetric"><div class="panel-heading"><div><span class="eyebrow">Definición</span><h2>Crear indicador</h2></div></div><div class="atlas-form-grid"><label>Nombre<input v-model="metricForm.name" required placeholder="Ej.: Flexiones en 60 segundos"></label><label>Categoría<select v-model="metricForm.category"><option>Rendimiento</option><option>Composición corporal</option><option>Cardiorrespiratorio</option><option>Movilidad</option><option>Salud</option><option>Otro</option></select></label><label>Unidad<input v-model="metricForm.unit" required placeholder="repeticiones, kg, cm, segundos"></label><label>Interpretación<select v-model="metricForm.direction"><option value="HigherIsBetter">Mayor es mejor</option><option value="LowerIsBetter">Menor es mejor</option><option value="Neutral">Sin dirección</option></select></label><label>Objetivo<input v-model.number="metricForm.targetValue" type="number" min="0" step="0.001"></label><label>Fecha objetivo<input v-model="metricForm.targetDate" type="date"></label><label class="wide">Protocolo<textarea v-model="metricForm.protocol" rows="2" placeholder="Cómo, cuándo y bajo qué condiciones repetir la medición"></textarea></label><label>Fuente o reglamento<input v-model="metricForm.sourceTitle" placeholder="Pendiente de confirmar si todavía no existe"></label><label>Enlace<input v-model="metricForm.sourceUrl" type="url"></label></div><div class="form-actions"><button type="button" class="secondary-button" @click="showNew=false">Cancelar</button><button class="primary-button">Crear indicador</button></div></form><div v-if="data" class="measurement-summary"><article><span>Indicadores</span><strong>{{data.metrics.length}}</strong></article><article><span>Registros</span><strong>{{data.totalEntries}}</strong></article><article><span>Con objetivo</span><strong>{{data.metricsWithTargets}}</strong></article></div><div v-if="data" class="measurement-workspace"><aside class="panel metric-list"><div class="panel-heading"><div><span class="eyebrow">Indicadores</span><h2>Seguimiento</h2></div></div><button v-for="m in data.metrics" :key="m.id" :class="{active:m.id===selectedId}" @click="selectedId=m.id"><span><strong>{{m.name}}</strong><small>{{m.category}} · {{m.unit}}</small></span><em>{{m.latestValue??'—'}}</em></button><p v-if="!data.metrics.length" class="list-empty">Todavía no creaste indicadores.</p></aside><main v-if="selected" class="metric-detail"><article class="panel metric-hero"><div><span class="eyebrow">{{selected.category}}</span><h2>{{selected.name}}</h2><p>{{selected.protocol||'Todavía no definiste un protocolo. Conviene hacerlo antes de comparar resultados.'}}</p></div><button class="primary-button" @click="showEntry=!showEntry">Registrar medición</button></article><form v-if="showEntry" class="panel entry-form" @submit.prevent="addEntry"><div class="atlas-form-grid"><label>Fecha<input v-model="entryForm.date" type="date" required></label><label>Resultado ({{selected.unit}})<input v-model.number="entryForm.value" type="number" min="0" step="0.001" required></label><label class="wide">Condiciones<input v-model="entryForm.conditions" placeholder="Hora, calentamiento, superficie, descanso previo..."></label><label class="wide">Notas<textarea v-model="entryForm.notes" rows="2"></textarea></label></div><button class="primary-button">Guardar medición</button></form><div class="metric-cards"><article><span>Último</span><strong>{{selected.latestValue??'—'}} {{selected.latestValue!==null?selected.unit:''}}</strong><small>{{fmt(selected.latestDate)}}</small></article><article><span>Mejor marca</span><strong>{{selected.bestValue??'—'}} {{selected.bestValue!==null?selected.unit:''}}</strong><small>{{selected.direction==='Neutral'?'Último valor':'Según la dirección elegida'}}</small></article><article><span>Objetivo</span><strong>{{selected.targetValue??'—'}} {{selected.targetValue!==null?selected.unit:''}}</strong><small>{{fmt(selected.targetDate)}}</small></article><article><span>Restante</span><strong>{{selected.remainingToTarget??'—'}} {{selected.remainingToTarget!==null?selected.unit:''}}</strong><small v-if="selected.targetValue===null">Sin objetivo definido</small></article></div><article class="panel metric-history"><div class="panel-heading"><div><span class="eyebrow">Evolución</span><h2>Historial</h2></div></div><div v-if="selected.entries.length" class="metric-chart"><div v-for="e in [...selected.entries].reverse()" :key="e.id"><span>{{e.value}}</span><i><b :style="{height:`${Math.max(4,e.value/maxValue*100)}%`}"></b></i><small>{{fmt(e.date)}}</small></div></div><div class="measurement-entries"><div v-for="e in selected.entries" :key="e.id"><strong>{{e.value}} {{selected.unit}}</strong><span>{{fmt(e.date)}}</span><p>{{e.conditions||'Condiciones no registradas'}}</p></div></div><p v-if="!selected.entries.length" class="list-empty">Registrá la primera medición para comenzar la evolución.</p></article><article v-if="selected.sourceTitle" class="panel metric-source"><span class="eyebrow">Fuente del protocolo</span><h2>{{selected.sourceTitle}}</h2><a v-if="selected.sourceUrl" :href="selected.sourceUrl" target="_blank" rel="noopener">Abrir fuente</a></article></main><article v-else class="panel empty-state"><h2>Creá un indicador</h2><p>Podés empezar por peso corporal o por una prueba física cuyo protocolo conozcas.</p></article></div></section></template>
